const values=v=>typeof v==='string'?[v]:Array.isArray(v)?v.flatMap(values):v&&typeof v==='object'?values(v.eng??v.ENG??v.en??Object.values(v)[0]):[];
const first=v=>values(v)[0]??'';
const rows=$input.all().flatMap((page,pageIndex)=>(page.json.notices??[]).map(n=>{
  const id=String(n['publication-number']??'');
  const body=[...new Set([...values(n['description-proc']),...values(n['description-lot'])].filter(Boolean))].join('\n').slice(0,20000);
  const deadlines=[...new Set(values(n['deadline-receipt-tender-date-lot']).map(v=>v.slice(0,10)).filter(v=>/^\d{4}-\d{2}-\d{2}$/.test(v)))];
  return {json:{source:'ted',external_id:id,source_url:'https://ted.europa.eu/en/notice/-/detail/'+id,title:first(n['notice-title']).slice(0,180)||'Notice '+id,organization:first(n['buyer-name']).slice(0,120)||'Unknown buyer',summary:body.slice(0,700)||'Official TED competition notice. Scope needs review.',published_at:String(n['publication-date']??'').slice(0,10),deadline:deadlines.length===1?deadlines[0]:null,ambiguous_deadline:deadlines.length>1,source_text:body},pairedItem:{item:pageIndex}}
})).filter(x=>x.json.external_id);
return rows.length?rows:[{json:{skip:true},pairedItem:{item:0}}];
